head.script:
scwin.fn_openPopup = function() {
    var options = {
        id: "popup1" + (i++),
        type: "window",
        width: "300px",
        height: "300px",
        //style: "top:50%;left:50%;transform: translateX(-50%) translateY(-50%);",
        popupName: "TestPage1",
        modal: true,
        useIFrame: false,
        //closeAction : "scwin.closePop", 
        resizable: false,
        status: false,
        menubar: false,
        scrollbars: false,
        title: true,
        xml: "<FORM>한글입니다</FORM>",
        useModalStack: true,
        dataObject: {
            type: "json",
            data: dataList1,
            name: "param1"
        }
    };
    pop = parent.$p.openPopup("engine_clearMemory_WPF_1950_(WSQ-3194).xml&aa=cc", options);
};
scwin.anchor1_onclick = function() {
    scwin.fn_openPopup();
};
scwin.onpageload = function() {
    window.pop;
    window.i = 0;
    dataList1.setData([["1", "2", "3"]]);
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
}
